CREATE VIEW LOAN_DETAILS AS SELECT l.*, m.full_name member_name,m.phone,b.title book_title,s.full_name issued_by FROM LOAN l JOIN MEMBER m USING(member_id) JOIN BOOK b USING(book_id) JOIN STAFF s USING(staff_id);
CREATE VIEW BOOK_AVAILABILITY AS SELECT b.book_id,b.title,COUNT(bc.copy_no) total_copies,COALESCE(SUM(bc.status='Available'),0) available_copies FROM BOOK b LEFT JOIN BOOK_COPY bc USING(book_id) GROUP BY b.book_id;
CREATE VIEW FINE_SUMMARY AS SELECT f.fine_no,f.amount,f.reason,f.fine_date,f.loan_id,l.member_id,m.full_name member_name,b.title book_title,COALESCE(SUM(p.amount_paid),0) total_paid,ROUND(f.amount-COALESCE(SUM(p.amount_paid),0),2) balance,CASE WHEN COALESCE(SUM(p.amount_paid),0)>=f.amount THEN 'Paid' WHEN COALESCE(SUM(p.amount_paid),0)>0 THEN 'Partially Paid' ELSE 'Unpaid' END status FROM FINE f JOIN LOAN l USING(loan_id) JOIN MEMBER m USING(member_id) JOIN BOOK b USING(book_id) LEFT JOIN PAYMENT p USING(fine_no) GROUP BY f.fine_no;
CREATE VIEW MEMBER_SUMMARY AS SELECT m.*,mp.plan_name,mp.max_books,mp.loan_days,(SELECT COUNT(*) FROM LOAN l WHERE l.member_id=m.member_id AND l.return_date IS NULL) open_loans,(SELECT COALESCE(SUM(balance),0) FROM FINE_SUMMARY fs WHERE fs.member_id=m.member_id) outstanding_fines FROM MEMBER m JOIN MEMBERSHIP_PLAN mp USING(plan_id);
CREATE VIEW OVERDUE_LOANS AS SELECT *,DATEDIFF(CURDATE(),due_date) days_overdue FROM LOAN_DETAILS WHERE return_date IS NULL AND due_date<CURDATE();
CREATE UNIQUE INDEX one_open_loan_per_copy ON LOAN(book_id,copy_no) WHERE return_date IS NULL;
CREATE UNIQUE INDEX one_pending_reservation ON RESERVATION(member_id,book_id) WHERE status='Pending';
CREATE TRIGGER loan_insert AFTER INSERT ON LOAN WHEN NEW.return_date IS NULL BEGIN UPDATE BOOK_COPY SET status='Borrowed' WHERE book_id=NEW.book_id AND copy_no=NEW.copy_no; END;
CREATE TRIGGER loan_return AFTER UPDATE OF return_date ON LOAN WHEN NEW.return_date IS NOT NULL BEGIN UPDATE BOOK_COPY SET status='Available' WHERE book_id=NEW.book_id AND copy_no=NEW.copy_no; END;
CREATE TRIGGER loan_delete AFTER DELETE ON LOAN WHEN OLD.return_date IS NULL BEGIN UPDATE BOOK_COPY SET status='Available' WHERE book_id=OLD.book_id AND copy_no=OLD.copy_no; END;
CREATE TRIGGER overpayment BEFORE INSERT ON PAYMENT WHEN NEW.amount_paid > (SELECT balance FROM FINE_SUMMARY WHERE fine_no=NEW.fine_no) BEGIN SELECT RAISE(ABORT,'Payment exceeds the outstanding balance.'); END;
